rules.css:
.hero.panel { box-sizing: border-box; max-width: var(--content-max-width); margin-inline: auto; padding: 0px; min-height: 0px; display: flex; flex-direction: column; border-bottom: 4px solid transparent; border-image: linear-gradient(
      to right,
      var(--accent-1) 0 25%,
      var(--accent-2) 25% 50%,
      var(--accent-3) 50% 75%,
      var(--accent-4) 75% 100%
    ) 1; }

header nav[aria-expanded="true"] { grid-template: 'brand hamburger' var(--nav-height)
    'sections sections' 1fr
    'tools tools' var(--nav-height) / 1fr auto; overflow-y: auto; min-height: 100dvh; }

header nav .nav-sections { background-color: var(--brand-navy); background-image: linear-gradient(
      to bottom,
      var(--brand-navy) 0,
      var(--brand-navy) 2px,
      #7298b7 2px,
      var(--brand-navy) 17px
    ); flex: 0 0 auto; }
